import{z as p,x as E,o as t,c as A,q as r,j as s,D as l,d as n,s as o,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"状态压缩 DP","description":"","frontmatter":{"title":"状态压缩 DP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bitmask-dp.md","filePath":"cs/bitmask-dp.md","lastUpdated":1791413859000}'),m={name:"cs/bitmask-dp.md"};function B(D,a,P,u,C,h){const i=E("Mermaid");return t(),A("div",null,[a[2]||(a[2]=r('<h1 id="状态压缩-dp" tabindex="-1">状态压缩 DP <a class="header-anchor" href="#状态压缩-dp" aria-label="Permalink to &quot;状态压缩 DP&quot;">​</a></h1><div class="epigraph"><p>子集或网格一行用比特掩码当状态下标；$2^n$ 个子集上转移，常 $O(3^n)$ 或 $O(2^n\\mathrm{poly})$。</p><footer>—— 据 Held and Karp, 1962 的子集 DP；CLRS 第 15 章整理</footer></div><p>上一课<a href="/cs/probability-dp">概率与期望 DP</a>把状态方程写在一般 \\(s\\) 上。主干<a href="/cs/dynamic-programming">动态规划</a>已给最优子结构。缺口是 \\(s\\subseteq\\{1..n\\}\\) 用整数掩码。哈密顿课的 Held–Karp 已是实例；本课把状压收成技法：旅行商、子集和、棋盘铺砖一行。不重写期望方程。后课树形 DP 换树。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\le 20\\) 时 \\(2^n\\) 可存。转移：枚举子集、子集的子集（\\(O(3^n)\\)：对每位 0/不选/选在子集）、或按位 SOS DP（\\(O(n2^n)\\)）点名。铺砖：第 \\(i\\) 行掩码与第 \\(i-1\\) 行兼容则转移。</p><p><span class="marginnote">数字实例：\\(n=20\\) 时 \\(2^{20}\\approx 10^6\\) 个状态，每个存一个 4 字节整数约 4 MB，一台手机都装得下；\\(n=40\\) 则是 \\(2^{40}\\approx 10^{12}\\) 个状态，几个 TB 起——状压的生死线就在这几十倍 \\(n\\) 上。</span></p><p>缺口是掩码，不是再证 NPC。精确 TSP 已讲，本课强调通用接口。</p><h3 id="不是把-硬压" tabindex="-1">不是把 \\(n=40\\) 硬压 <a class="header-anchor" href="#不是把-硬压" aria-label="Permalink to &quot;不是把 $n=40$ 硬压&quot;">​</a></h3><p>\\(2^{40}\\) 内存爆炸。要折半、meet-in-the-middle 或换算法。不要「状压万能」。</p><p><span class="marginnote">Held–Karp 子集。SOS DP 是高维前缀。后课插头 DP 是网格边界轮廓，比一行掩码更细。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编码占用/奇偶/颜色到比特。预处理合法掩码列表。转移循环 <code>for s</code> <code>for t subset s</code> 或滚动数组两行。</p>',12)),(t(),s(d,null,{default:l(()=>[o(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SET%5B%22%E5%AD%90%E9%9B%86%20S%22%5D%20--%3E%20MASK%5B%22%E6%AF%94%E7%89%B9%E6%8E%A9%E7%A0%81%22%5D%0A%20%20MASK%20--%3E%20DP%5B%22dp%5Bs%5D%20%E6%88%96%20dp%5Bi%5D%5Bs%5D%22%5D%0A%20%20DP%20--%3E%20TR%5B%22%E6%9E%9A%E4%B8%BE%E5%AD%90%E6%8E%A9%E7%A0%81%20%2F%20%E5%85%BC%E5%AE%B9%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},[n("术语翻译：掩码（mask）就是一个二进制数，第 \\(i\\) 位是 1 表示「第 \\(i\\) 个元素在集合里」。比如集合 {0, 2} 写成二进制 101，也就是整数 5——于是「集合」变成了能当下标的普通整数，放进数组就是 "),e("code",null,"dp[5]"),n("。")])],-1)),a[4]||(a[4]=e("p",null,[n("位运算 "),e("code",null,"__builtin_ctz"),n(" 枚举。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"状态空间指数但 \\(n\\) 小则多项式于 \\(2^n\\)。与生成函数：子集卷积可用 Walsh/NTT，本课朴素 \\(3^n\\) 先会。与线性基：都是比特，一个优化一个 DP。",-1)),a[7]||(a[7]=e("p",null,"铺砖的一行内转移长什么样，值得单独画：第 \\(i\\) 行的轮廓决定第 \\(i+1\\) 行哪些掩码合法。",-1)),(t(),s(d,null,{default:l(()=>[o(i,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20PREV%5B%22%E7%AC%AC%20i-1%20%E8%A1%8C%E6%8E%A9%E7%A0%81%22%5D%20--%3E%20COMP%7B%22%E4%B8%8E%E7%AC%AC%20i%20%E8%A1%8C%E5%85%BC%E5%AE%B9%E5%90%97%22%7D%0A%20%20COMP%20--%3E%7C%22%E7%AB%96%E5%9D%97%E5%8D%A0%E4%BD%8D%E5%86%B2%E7%AA%81%22%7C%20SKIP%5B%22%E8%B7%B3%E8%BF%87%E8%AF%A5%E7%BB%84%E5%90%88%22%5D%0A%20%20COMP%20--%3E%7C%22%E6%97%A0%E5%86%B2%E7%AA%81%22%7C%20CUR%5B%22dp%5Bi%5D%5B%E6%9C%AC%E8%A1%8C%E6%8E%A9%E7%A0%81%5D%20%E6%9B%B4%E6%96%B0%22%5D%0A%20%20CUR%20--%3E%20NEXT%5B%22%E6%BB%9A%E5%85%A5%E7%AC%AC%20i%2B1%20%E8%A1%8C%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=r('<p><span class="marginnote">「枚举子集的子集是 \\(O(3^n)\\)」可以这么直觉化：把三元组（全集、子集 \\(S\\)、\\(S\\) 的子集 \\(T\\)）摊到每个元素头上，每个元素只有三种角色——不在 \\(S\\)、在 \\(S\\) 但不在 \\(T\\)、在 \\(T\\)。三种选择相乘就是 \\(3^n\\)，而不是先数子集再数子集的 \\(4^n\\)。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部 SOS 恒等式。不写量子。后课默认：\\(n\\le 20\\) 子集问题优先状压。下一课树形 DP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>掩码下标 = 子集；转移枚举子掩码或兼容行。</li><li>\\(O(3^n)\\)、\\(O(n2^n)\\) 是常见界。</li><li>\\(n\\) 稍大即不可用。</li><li>出处：Held and Karp, 1962；CLRS 第 15 章。</li></ul>',5))])}const f=p(m,[["render",B]]);export{S as __pageData,f as default};
